// emigration-enclave-place.js
//
// The Cultural Enclave as a REAL tile. When the player recognizes an enclave (a stance other than
// "ignore"), this places that origin's, that stance's enclave IMPROVEMENT
// (IMPROVEMENT_EMIG_ENCLAVE_<CIV>_<A|B>, generated by scripts/gen-enclave-improvements.mjs) on one of the
// host city's plots with the engine's own CREATE_ELEMENT operation. The tile then carries the stance's
// benefit yield NATIVELY (it shows in the city's yields like any improvement), settles one population
// point, and paints its civ symbol on the map (emigration-enclave-markers.js). The per-turn benefit
// grant steps aside while the tile stands (emigration-quarter.js); the drawback stays on the grant path.
//
// Why this is safe now: the improvements are never buildable (RequiresUnlock with no unlock row,
// CityBuildable false), so the AI's build evaluator never sees them. Watched in-game 2026-09-12: a
// never-buildable custom improvement placed this way carried its yields and survived seven AI turns on a
// human city and on an AI city (devtools/engine-probe/, runs 7 and 8). The July crash was specific to a
// BUILDABLE custom improvement.
//
// Tile choice: an empty owned land plot of the city (no district, no constructible, flat or hill), the
// nearest to the centre first (an enclave grows at the city's edge, not in its outer fields); if the
// city has no empty plot, its outlying rural improvement farthest from the centre is replaced (that
// community takes over the farmstead). Everything degrades to "not placed" (the grant keeps paying).

import { CONFIG } from "/emigration/ui/emigration-config.js";
import { dlog } from "/emigration/ui/emigration-log.js";
import { listDepartureTiles, rankDepartureTiles } from "/emigration/ui/emigration-departure-tile.js";
import { VILLAGE_TYPE, skinCandidates } from "/emigration/ui/emigration-enclave-skins.js";
import { scheduleDistrictCleanup } from "/emigration/ui/emigration-plot-cleanup.js";
export { VILLAGE_TYPE } from "/emigration/ui/emigration-enclave-skins.js";

/** Prefix shared with the generator and the markers. */
export const ENCLAVE_PREFIX = "IMPROVEMENT_EMIG_ENCLAVE_";
/** The skin modes (CONFIG.enclaveTileSkin). */
export const SKIN = Object.freeze({ NATIVE: 0, THEMED: 1, VILLAGE: 2 });

/** The configured skin mode (defaults to themed on an unknown value). @returns {number} A SKIN value. */
export function skinMode() {
  const v = Number(CONFIG.enclaveTileSkin);
  return v === SKIN.NATIVE || v === SKIN.VILLAGE ? v : SKIN.THEMED;
}

/**
 * The ordered constructible types to try for an enclave, by skin mode: themed = the origin's unique
 * improvement, then fallbacks by stance yield, then the Village (emigration-enclave-skins.js); village =
 * the Village only; native = the per-civ enclave improvement itself. Pure.
 * @param {string} enclaveType The enclave improvement type (enclaveTypeFor).
 * @param {string|null|undefined} originCiv The origin CivilizationType.
 * @returns {string[]} Types to try, best first.
 */
export function placedTypesFor(enclaveType, originCiv) {
  const mode = skinMode();
  if (mode === SKIN.NATIVE) return [enclaveType];
  if (mode === SKIN.VILLAGE) return [VILLAGE_TYPE];
  return skinCandidates(originCiv);
}

/**
 * The terrain types a constructible may stand on (its Constructible_ValidTerrains rows); an EMPTY set
 * means the data lists none, i.e. any land the enclave picker allows.
 * @param {string} type A ConstructibleType. @returns {Set<string>} Terrain types.
 */
export function validTerrainsFor(type) {
  return safe(() => {
    const rows = GameInfo.Constructible_ValidTerrains;
    if (!rows || typeof rows.filter !== "function") return new Set();
    const mine = rows.filter((/** @type {*} */ r) => r.ConstructibleType === type);
    return new Set(mine.map((/** @type {*} */ r) => String(r.TerrainType)));
  }, new Set());
}

/**
 * The enclave improvement type a placement record stands for (its icon and label), whichever skin was
 * placed: the record's `enclave` field, else its placed type. Pure.
 * @param {*} rec A quarter record. @returns {string|null} The enclave type, or null when nothing was placed.
 */
export function enclaveTypeOf(rec) {
  const p = rec && rec.placed;
  if (!p) return null;
  if (typeof p.enclave === "string" && p.enclave) return p.enclave;
  return typeof p.type === "string" && p.type.startsWith(ENCLAVE_PREFIX) ? p.type : null;
}
const VALID_TERRAINS = new Set(["TERRAIN_FLAT", "TERRAIN_HILL"]);

/**
 * Run a game read that may be unavailable or throw, degrading to `fb`.
 * @param {() => *} fn The read. @param {*} [fb] Fallback. @returns {*} The value or fallback.
 */
function safe(fn, fb) {
  try {
    return fn();
  } catch (_) {
    return fb;
  }
}

/**
 * The improvement type for an origin civ and stance: the exact inverse of the generator's `typeOf`
 * (CIVILIZATION_ROME + "a" → IMPROVEMENT_EMIG_ENCLAVE_ROME_A). Pure.
 * @param {string|null|undefined} originCiv The origin CivilizationType.
 * @param {string|null|undefined} optionId The stance ("a" | "b"); "ignore"/absent yields null.
 * @returns {string|null} The ConstructibleType, or null.
 */
export function enclaveTypeFor(originCiv, optionId) {
  if (typeof originCiv !== "string" || !originCiv.length) return null;
  if (optionId !== "a" && optionId !== "b") return null;
  const short = originCiv.replace(/^CIVILIZATION_/, "");
  return short ? ENCLAVE_PREFIX + short + "_" + optionId.toUpperCase() : null;
}

/**
 * Whether the enclave data is loaded in this game (the generated rows exist in GameInfo).
 * @param {string} type A ConstructibleType.
 * @returns {number|null} The constructible's `$index` when loaded, else null.
 */
export function enclaveIndex(type) {
  return safe(() => {
    const def = GameInfo.Constructibles.lookup(type);
    return def && typeof def.$index === "number" ? def.$index : null;
  }, null);
}

/**
 * The ConstructibleType names standing on a plot ([] when unreadable).
 * @param {number} x Plot x. @param {number} y Plot y. @returns {string[]} Types on the plot.
 */
function typesAt(x, y) {
  return safe(() => {
    /** @type {string[]} */
    const out = [];
    for (const id of (MapConstructibles.getConstructibles(x, y) || [])) {
      const inst = Constructibles.getByComponentID(id);
      const def = inst ? GameInfo.Constructibles.lookup(inst.type) : null;
      if (def && typeof def.ConstructibleType === "string") out.push(def.ConstructibleType);
    }
    return out;
  }, []);
}

/**
 * The enclave improvement standing on a plot, or null (the native skin only; a Village-skinned enclave is
 * known from its quarter record, see enclaveStanding).
 * @param {number} x Plot x. @param {number} y Plot y.
 * @returns {string|null} The enclave ConstructibleType, or null.
 */
export function enclaveTypeAt(x, y) {
  return typesAt(x, y).find((t) => t.startsWith(ENCLAVE_PREFIX)) || null;
}

/**
 * Whether a quarter record's placed enclave still stands on its plot (pillage, razing, or an age
 * transition may have removed it; then the stance grant resumes).
 * @param {*} rec A quarter record.
 * @returns {boolean} True when the tile stands.
 */
export function enclaveStanding(rec) {
  const p = rec && rec.placed;
  if (!p || typeof p.plot !== "number") return false;
  const loc = safe(() => GameplayMap.getLocationFromIndex(p.plot), null);
  if (!loc) return false;
  return typesAt(loc.x, loc.y).includes(p.type);
}

/**
 * The yields of a plot as its owner sees them ({YIELD_X: n}), or null when unreadable.
 * @param {number} plot Plot index. @param {number} owner The plot owner's player id.
 * @returns {Record<string, number>|null} Yields by type.
 */
export function plotYieldsAt(plot, owner) {
  return safe(() => {
    const pairs = GameplayMap.getYields(plot, owner);
    if (!Array.isArray(pairs)) return null;
    /** @type {Record<string, number>} */
    const out = {};
    for (const p of pairs) {
      const def = GameInfo.Yields.lookup(p[0]);
      const type = def && def.YieldType ? String(def.YieldType) : String(p[0]);
      const n = Number(p[1]);
      if (n) out[type] = (out[type] || 0) + n;
    }
    return out;
  }, null);
}

/**
 * The yields a constructible type carries natively ({YIELD_X: n}): its Constructible_YieldChanges rows,
 * plus the Village's +2 Culture from data/emigration-enclave-village.xml (a modifier, not a row).
 * @param {string} type A ConstructibleType. @returns {Record<string, number>} Yields by type.
 */
export function nativeYieldsOf(type) {
  /** @type {Record<string, number>} */
  const out = {};
  safe(() => {
    const rows = GameInfo.Constructible_YieldChanges;
    if (!rows || typeof rows.filter !== "function") return;
    for (const r of rows.filter((/** @type {*} */ x) => x.ConstructibleType === type)) {
      out[String(r.YieldType)] = (out[String(r.YieldType)] || 0) + (Number(r.YieldChange) || 0);
    }
  });
  if (type === VILLAGE_TYPE) out.YIELD_CULTURE = (out.YIELD_CULTURE || 0) + 2;
  return out;
}

/**
 * What a takeover must pay back each turn so the tile ends up with base + the REPLACED improvement's
 * yields + the enclave's own: `before` (the plot with the replaced improvement) plus the enclave type's
 * native yields, minus what the plot yields now with the enclave standing, per yield, never below zero.
 * Pure over its inputs; called once the tile is first seen standing.
 * @param {Record<string, number>} before The plot's yields before the takeover.
 * @param {Record<string, number>} native The enclave type's native yields.
 * @param {Record<string, number>} after The plot's yields with the enclave standing.
 * @returns {Record<string, number>} Per-yield shortfall to compensate (empty when nothing was lost).
 */
export function takeoverCompensation(before, native, after) {
  /** @type {Record<string, number>} */
  const out = {};
  const b = before || {}, n = native || {}, a = after || {};
  for (const k of new Set([...Object.keys(b), ...Object.keys(n), ...Object.keys(a)])) {
    const gap = Math.round((num(b[k]) + num(n[k]) - num(a[k])) * 100) / 100;
    if (gap > 0) out[k] = gap;
  }
  return out;
}

/** A finite number or 0. @param {*} v Any value. @returns {number} The number. */
function num(v) {
  const n = Number(v);
  return isFinite(n) ? n : 0;
}

/**
 * Remove a record's placed tile from the map (the enclave fades): the constructible of the placed type on
 * that plot is destroyed with the engine's DESTROY_ELEMENT. Nothing else on the plot is touched.
 * @param {*} rec A quarter record. @returns {boolean} True when a destroy request was issued.
 */
export function destroyPlacedTile(rec) {
  const p = rec && rec.placed;
  if (!p || typeof p.plot !== "number") return false;
  return safe(() => {
    const loc = GameplayMap.getLocationFromIndex(p.plot);
    for (const id of (MapConstructibles.getConstructibles(loc.x, loc.y) || [])) {
      const inst = Constructibles.getByComponentID(id);
      const def = inst ? GameInfo.Constructibles.lookup(inst.type) : null;
      if (!def || def.ConstructibleType !== p.type) continue;
      const sender = typeof GameContext !== "undefined" ? GameContext.localPlayerID : id.owner;
      Game.PlayerOperations.sendRequest(sender, "DESTROY_ELEMENT", { Kind: "CONSTRUCTIBLE", Owner: id.owner, LocalID: id.id });
      dlog("enclave tile removed " + p.type + " at plot " + p.plot);
      scheduleDistrictCleanup(p.plot); // keep the plot usable once the enclave is gone
      return true;
    }
    return false;
  }, false);
}

/**
 * Whether a record's placed plot holds ANY constructible now (a wonder, building, or other improvement
 * that displaced the enclave tile). False for an empty plot or an unreadable record.
 * @param {*} rec A quarter record. @returns {boolean} True when something stands on the plot.
 */
export function placedPlotOccupied(rec) {
  const p = rec && rec.placed;
  if (!p || typeof p.plot !== "number") return false;
  const loc = safe(() => GameplayMap.getLocationFromIndex(p.plot), null);
  return !!loc && (safe(() => MapConstructibles.getConstructibles(loc.x, loc.y), null) || []).length > 0;
}

/**
 * Whether the standing placed tile IS the enclave's benefit, so the per-turn benefit grant steps aside
 * (the drawback stays on the grant). True for every skin while the tile stands: the native improvement
 * carries the stance yield, a unique or fallback skin its own native yield (+2 to +5), the Village +2
 * Culture. False when nothing stands, so the grant resumes after pillage, razing, or displacement.
 * @param {*} rec A quarter record. @returns {boolean} True when the tile pays the benefit itself.
 */
export function enclaveCarriesBenefit(rec) {
  return enclaveStanding(rec);
}

/**
 * The terrain type name of a plot ("" when unreadable).
 * @param {number} x Plot x. @param {number} y Plot y. @returns {string} Terrain type.
 */
function terrainAt(x, y) {
  return safe(() => {
    const t = GameInfo.Terrains.lookup(GameplayMap.getTerrainType(x, y));
    return t && t.TerrainType ? String(t.TerrainType) : "";
  }, "");
}

/**
 * The city's empty, land, flat-or-hill plots with no district and no constructible, nearest first.
 * Pure over the injected reads, so it is unit-testable with a stubbed map.
 * @param {*} city The host city object.
 * @returns {{plot:number, loc:{x:number,y:number}, distance:number}[]} Candidates, nearest first.
 */
export function emptyPlotsOf(city) {
  /** @type {{plot:number, loc:{x:number,y:number}, distance:number}[]} */
  const out = [];
  const plots = safe(() => city.getPurchasedPlots(), null) || [];
  const centre = (city && city.location) || { x: 0, y: 0 };
  for (const plot of plots) {
    const loc = safe(() => GameplayMap.getLocationFromIndex(plot), null);
    if (!loc || !isEmptyLandPlot(loc, centre)) continue;
    out.push({ plot, loc, distance: safe(() => GameplayMap.getPlotDistance(loc.x, loc.y, centre.x, centre.y), 0) });
  }
  return out.sort((a, b) => a.distance - b.distance || a.plot - b.plot);
}

/**
 * Whether a plot can host the enclave: not the centre, land, no district, no constructible, flat/hill.
 * @param {{x:number,y:number}} loc Plot location. @param {{x:number,y:number}} centre City centre.
 * @returns {boolean} True when usable.
 */
function isEmptyLandPlot(loc, centre) {
  if (loc.x === centre.x && loc.y === centre.y) return false;
  if (safe(() => GameplayMap.isWater(loc.x, loc.y), false)) return false;
  if (safe(() => Districts.getAtLocation(loc), null)) return false;
  if ((safe(() => MapConstructibles.getConstructibles(loc.x, loc.y), null) || []).length) return false;
  return VALID_TERRAINS.has(terrainAt(loc.x, loc.y));
}

/**
 * Issue the CREATE_ELEMENT for the enclave improvement on a plot (the tuner's argument shape).
 * @param {*} city Host city. @param {number} typeIndex The constructible `$index`.
 * @param {{x:number,y:number}} loc The plot location.
 * @param {boolean} needsDistrict Whether the plot has no district yet (an empty plot).
 * @returns {boolean} True when the request was issued.
 */
function create(city, typeIndex, loc, needsDistrict) {
  return safe(() => {
    const sender = typeof GameContext !== "undefined" ? GameContext.localPlayerID : city.owner;
    // An improvement needs its rural district; an EMPTY plot has none, so create it first (the tuner's
    // district mode). A plot that held an improvement keeps its district and skips this.
    if (needsDistrict) {
      Game.PlayerOperations.sendRequest(sender, "CREATE_ELEMENT", { Kind: "DISTRICT", Type: "DISTRICT_RURAL", Location: loc, Parent: city.id, Owner: city.owner });
    }
    Game.PlayerOperations.sendRequest(sender, "CREATE_ELEMENT", { Kind: "CONSTRUCTIBLE", Type: typeIndex, Location: loc, Parent: city.id, Owner: city.owner });
    return true;
  }, false);
}

/**
 * Place the enclave improvement for a recognized stance. Returns what was placed, or null when the
 * option is off, the data is not loaded, the stance is "ignore", or the city has no usable plot.
 * @param {*} city The host city object.
 * @param {string|null} originCiv The origin CivilizationType.
 * @param {string} optionId The chosen stance.
 * @returns {{type:string, plot:number, enclave:string, replaced?:string}|null} The placement, or null:
 *   `type` is what stands on the map (the Village or the enclave improvement), `enclave` the enclave
 *   improvement type the record stands for (icon, label).
 */
export function placeEnclave(city, originCiv, optionId) {
  if (!CONFIG.quarterPlaceImprovement || !city) return null;
  const enclave = enclaveTypeFor(originCiv, optionId);
  if (!enclave) return null;
  const empty = emptyPlotsOf(city);
  const farms = rankDepartureTiles(listDepartureTiles(city));
  for (const type of placedTypesFor(enclave, originCiv)) {
    const index = enclaveIndex(type);
    if (index == null) continue; // not loaded in this age (a later age's improvement)
    const fits = terrainFilter(type);
    const pick = empty.find(fits);
    if (pick) return placeOnEmpty(city, type, index, enclave, pick);
    const tile = farms.find(fits);
    if (tile) return takeOverFarmstead(city, type, index, enclave, tile);
  }
  dlog("enclave " + enclave + ": no skin type loaded with a valid plot in " + safe(() => Locale.compose(city.name), "?"));
  return null;
}

/**
 * A plot predicate for a type's valid terrains (every plot when the data lists none).
 * @param {string} type A ConstructibleType. @returns {(c:{loc:{x:number,y:number}}) => boolean} The filter.
 */
function terrainFilter(type) {
  const terrains = validTerrainsFor(type);
  // Land only: every skin is a land improvement, and a takeover candidate can be a fishing boat (watched
  // 2026-09-13: a caravanserai went onto a water plot).
  return (c) => !safe(() => GameplayMap.isWater(c.loc.x, c.loc.y), false)
    && (!terrains.size || terrains.has(terrainAt(c.loc.x, c.loc.y)));
}

/**
 * Place a skin type on an EMPTY plot (rural district first, then the improvement).
 * @param {*} city Host city. @param {string} type The type placed. @param {number} index Its `$index`.
 * @param {string} enclave The enclave improvement type the record stands for.
 * @param {{plot:number, loc:{x:number,y:number}}} pick The empty plot.
 * @returns {{type:string, plot:number, enclave:string}|null} The placement, or null.
 */
function placeOnEmpty(city, type, index, enclave, pick) {
  if (!create(city, index, pick.loc, true)) return null;
  dlog("enclave placed " + type + " for " + enclave + " at plot " + pick.plot + " (new rural district)");
  return { type, plot: pick.plot, enclave };
}

/**
 * No empty plot: the enclave takes over the outlying farmstead (destroy it, then place on its plot).
 * @param {*} city Host city. @param {string} type The type placed. @param {number} index Its `$index`.
 * @param {string} enclave The enclave improvement type the record stands for.
 * @param {import("/emigration/ui/emigration-departure-tile.js").DepartureTile} tile The farmstead to replace.
 * @returns {{type:string, plot:number, enclave:string, replaced:string, before?:Record<string,number>}|null} The
 *   placement (with the plot's yields before the takeover when readable), or null.
 */
function takeOverFarmstead(city, type, index, enclave, tile) {
  const before = plotYieldsAt(tile.plot, city.owner); // what the farmstead gave; paid back while the enclave stands
  const destroyed = safe(() => {
    const sender = typeof GameContext !== "undefined" ? GameContext.localPlayerID : city.owner;
    Game.PlayerOperations.sendRequest(sender, "DESTROY_ELEMENT", { Kind: "CONSTRUCTIBLE", Owner: tile.elem.owner, LocalID: tile.elem.id });
    return true;
  }, false);
  if (!destroyed || !create(city, index, tile.loc, false)) return null;
  dlog("enclave placed " + type + " for " + enclave + " at plot " + tile.plot + " replacing " + tile.type);
  /** @type {{type:string, plot:number, enclave:string, replaced:string, before?:Record<string,number>}} */
  const out = { type, plot: tile.plot, enclave, replaced: tile.type };
  if (before) out.before = before;
  return out;
}
